    i_set_b,
    o_psr);

  input        clk;
  input        rst_x;
  input        i_c;
  input        i_set_c;
  input        i_i;
  input        i_set_i;
  input        i_v;
  input        i_set_v;
  input        i_d;
  input        i_set_d;
  input        i_n;
  input        i_set_n;
  input        i_z;
